const concepts = {
  cpu: { definition: 'A scheduler chooses which ready incident process receives the CPU next.', formulas: 'WT = TAT − BT; RT = first start − arrival; TAT = completion − arrival; utilization = busy ticks ÷ elapsed ticks.', guarantee: 'Optimality depends on assumptions: SJF minimizes mean waiting only when all jobs arrive together with known bursts; EDF is optimal for independent preemptible uniprocessor jobs under its standard assumptions.', myths: ['A low average wait does not mean every process receives a short response.', 'A simulated deadline result is not a real golden-hour prediction.'], viva: [['How are ties resolved?', 'Arrival time, then numeric-aware PID; RR enqueues boundary arrivals before the expired process.'], ['What does lower priority number mean?', 'Higher priority in this laboratory.'], ['Why record idle time?', 'It keeps elapsed time and CPU utilization honest.']] },
  process: { definition: 'A process is a program in execution with state, registers, resources, and scheduling information.', formulas: 'Program counter advances by one per simulated instruction; I/O wait is counted in virtual ticks.', guarantee: 'The model demonstrates state transitions and burst sequencing; it does not create OS processes.', myths: ['A WAITING process is not ready for the CPU.', 'A context switch is control-state work, not useful process execution.'], viva: [['What is stored in a PCB?', 'Process identity, state, program counter, priority, resource and accounting information.'], ['Why block on I/O?', 'A process waiting for an external event should not occupy the CPU.'], ['What is fork?', 'A parent creates a child process with an identifiable relationship.']] },
  sync: { definition: 'Synchronization coordinates concurrent access to shared state.', formulas: 'Lost updates are visible when actual shared count differs from expected initial count minus completed dispatches.', guarantee: 'A mutex serializes its critical section. Peterson is shown under sequential consistency only.', myths: ['A race can produce a plausible value by coincidence.', 'A semaphore is not interchangeable with every mutex use.'], viva: [['What is a critical section?', 'The part that accesses shared mutable data.'], ['What are Peterson assumptions?', 'Two participants and sequentially consistent reads/writes in this model.'], ['Why must wait/signal be atomic?', 'Interleaving the permit update can violate the semaphore invariant.']] },
  deadlock: { definition: 'Deadlock is a set of processes permanently waiting for resources held within the same set.', formulas: 'Banker Need = Max − Allocation; a safe sequence repeatedly finishes any process whose Need ≤ Work.', guarantee: 'Banker avoids unsafe states only when maximum claims are known; a wait-for cycle is sufficient for single-instance resources.', myths: ['Unsafe is not the same as currently deadlocked.', 'Breaking any one Coffman condition prevents deadlock only if it is actually enforced.'], viva: [['Name the four conditions.', 'Mutual exclusion, hold-and-wait, no preemption, circular wait.'], ['What is a safe state?', 'At least one order lets each process finish with available plus released resources.'], ['Can a refused request mutate state?', 'No; tentative state is discarded.']] },
  ipc: { definition: 'IPC exchanges data and events among independent processes.', formulas: 'Message-passing bytes copied = messages × payload bytes in this configured model.', guarantee: 'Counts describe the entered workload, not universal timing or throughput.', myths: ['Shared memory is fast but needs synchronization.', 'A signal interrupts control flow; it is not a general data channel.'], viva: [['What is a mailbox?', 'A bounded queue used to exchange discrete messages.'], ['What does a full blocking pipe do?', 'It suspends the writer until the reader makes space.'], ['What is saved on interruption?', 'The execution context needed to resume the task.']] },
  memory: { definition: 'Memory management maps process addresses to physical storage and tracks free space.', formulas: 'Physical address = frame × page size + offset; EAT = h(TLB+M)+(1−h)(TLB+2M).', guarantee: 'The lab uses synthetic sizes and addresses; fragmentation is measured within the selected model.', myths: ['External fragmentation is about free-space shape, not total bytes alone.', 'A segmentation limit is exclusive in this implementation.'], viva: [['What is internal fragmentation?', 'Allocated space unused inside a fixed-size block or final page.'], ['What does a TLB cache?', 'Recent virtual-page to physical-frame translations.'], ['Why does compaction help?', 'It combines scattered free holes into one larger region.']] },
  virtual: { definition: 'Virtual memory keeps a working set resident in a limited set of page frames.', formulas: 'Hit ratio = hits ÷ references; fault count is the number of misses.', guarantee: 'Optimal is an offline lower bound because it uses future references; LRU has the stack property.', myths: ['More frames do not reduce FIFO faults for every reference string.', 'A high fault count is a workload/frame observation, not a diagnosis of a real host.'], viva: [['What is Belady’s anomaly?', 'FIFO may fault more after its frame count increases.'], ['Why is Optimal not implementable online?', 'It needs future references.'], ['What is thrashing?', 'Excessive paging that leaves too little useful execution.']] },
  disk: { definition: 'Disk scheduling orders pending track requests to reduce head movement or improve fairness.', formulas: 'Movement = sum of absolute adjacent track differences; mean seek = movement ÷ request count.', guarantee: 'SSTF minimizes the next seek locally, not total cost for every queue, and can starve distant requests under continuing arrivals.', myths: ['LOOK turns at the last request, not the physical endpoint.', 'C-SCAN wrap movement is included in this model.'], viva: [['How does SCAN differ from LOOK?', 'SCAN visits the disk end before reversing; LOOK reverses at the last request.'], ['Why can SSTF starve?', 'New nearby requests can repeatedly bypass a far request.'], ['What does indexed allocation trade?', 'An index block enables direct lookup with index-storage overhead.']] },
};

concepts.beds = { definition: 'A hospital bed pool is a counting semaphore: admitting a patient is wait(), discharge is signal(), and patients beyond beds plus boarding places are diverted.', formulas: 'a = λ/μ; Erlang-B B(c,a); M/M/c/K diversion P_K; λ_eff = λ(1−P_K); W_q = L_q/λ_eff; priority wait W_k = C(c,a) / [cμ(1−σ_{k−1})(1−σ_k)].', guarantee: 'Results are exact for Poisson arrivals and exponential stays with identical beds. Real stays are heavier-tailed, so treat them as planning estimates; the Monte-Carlo cross-check shows how closely a simulation agrees with the formulas.', myths: ['Average occupancy below 100% does not mean no diversions: random arrival bunching fills beds even at 85% load.', 'Adding beds helps less than expected near saturation, but far more than linearly when the system is overloaded.', 'A bed shortfall is not a staffing shortfall: nurses and ventilators are separate resources (see the Banker panel).'], viva: [['Why Erlang-B and not just utilisation?', 'Utilisation hides variability; Erlang-B gives the probability that an arrival finds every bed busy.'], ['What does the priority formula assume?', 'A common service rate across classes and non-preemptive service, so a critical patient never evicts one already in a bed.'], ['Why can the Banker test refuse an admission when beds are free?', 'Admitting could leave patients holding some resources while waiting forever for others (a deadlock-prone state).']] };

let playState = { index: 0, total: 0, playing: false, speed: 1 };
const playListeners = new Set();
const emitPlay = patch => { playState = { ...playState, ...patch }; playListeners.forEach(listener => listener()); };
const subscribePlay = listener => { playListeners.add(listener); return () => playListeners.delete(listener); };
const getPlay = () => playState;

function Playback({ result }) {
  const play = useSyncExternalStore(subscribePlay, getPlay, getPlay);
  const lastTime = useRef(0); const fractional = useRef(0);
  useEffect(() => { emitPlay({ total: result?.snapshots?.length || 0, index: 0, playing: false }); }, [result]);
  useEffect(() => {
    let raf;
    const tick = now => {
      if (playState.playing && playState.total) {
        const delta = lastTime.current ? Math.min(100, now - lastTime.current) : 0; lastTime.current = now;
        fractional.current += delta * playState.speed / 700;
        if (fractional.current >= 1) { const jump = Math.floor(fractional.current); fractional.current -= jump; const index = Math.min(playState.total - 1, playState.index + jump); emitPlay({ index, playing: index < playState.total - 1 }); }
      } else lastTime.current = 0;
      raf = requestAnimationFrame(tick);
    };
    raf = requestAnimationFrame(tick); return () => cancelAnimationFrame(raf);
  }, []);
  useEffect(() => {
    const key = event => {
      if (event.target instanceof HTMLInputElement || event.target instanceof HTMLSelectElement || event.target instanceof HTMLTextAreaElement) return;
      if (event.code === 'Space') { event.preventDefault(); emitPlay({ playing: !playState.playing }); }
      if (event.key === 'ArrowRight') emitPlay({ index: Math.min(playState.total - 1, playState.index + 1) });
      if (event.key === 'ArrowLeft') emitPlay({ index: Math.max(0, playState.index - 1) });
      if (event.key === '[') emitPlay({ speed: Math.max(.25, playState.speed / 2) });
      if (event.key === ']') emitPlay({ speed: Math.min(8, playState.speed * 2) });
    };
    window.addEventListener('keydown', key); return () => window.removeEventListener('keydown', key);
  }, []);
  const set = patch => emitPlay(patch);
  const jumpEvent = direction => {
    if (!result?.events?.length) return;
    const current = result.snapshots?.[play.index]?.t ?? 0;
    const candidates = result.events.filter(event => event.type === 'DISPATCH' || event.type === 'PREEMPT' || event.type === 'TERMINATE');
    const target = direction > 0 ? candidates.find(event => event.t > current) : [...candidates].reverse().find(event => event.t < current);
    if (target) set({ index: result.snapshots.findIndex(snapshot => snapshot.t >= target.t) });
  };
  const bounded = Math.max(0, Math.min(play.total - 1, play.index));
  return <div className="mt-4 rounded-xl border border-slate-200 bg-slate-50 p-3 dark:border-slate-700 dark:bg-slate-900" aria-label="Simulation transport controls">
    <div className="flex flex-wrap items-center gap-2">
      <button className="secondary" onClick={() => set({ index: 0, playing: false })} disabled={!play.total}>|◀ Start</button>
      <button className="secondary" onClick={() => set({ index: Math.max(0, bounded - 1), playing: false })} disabled={!play.total}>◀ Step</button>
      <button className="primary" onClick={() => set({ playing: !play.playing })} disabled={!play.total}>{play.playing ? 'Pause' : 'Play'}</button>
      <button className="secondary" onClick={() => set({ index: Math.min(play.total - 1, bounded + 1), playing: false })} disabled={!play.total}>Step ▶</button>
      <button className="secondary" onClick={() => jumpEvent(-1)} disabled={!play.total}>◀ Event</button>
      <button className="secondary" onClick={() => jumpEvent(1)} disabled={!play.total}>Event ▶</button>
      <button className="secondary" onClick={() => set({ index: play.total - 1, playing: false })} disabled={!play.total}>End ▶|</button>
      <label className="ml-auto !flex-row items-center gap-2">Speed<select value={play.speed} onChange={e => set({ speed: Number(e.target.value) })}>{[.25,.5,1,2,4,8].map(speed => <option key={speed} value={speed}>{speed}×</option>)}</select></label>
    </div>
    <div className="mt-3 flex items-center gap-3"><span className="min-w-20 text-xs font-bold">Step {bounded}/{Math.max(0, play.total - 1)}</span><input className="flex-1" type="range" min="0" max={Math.max(0, play.total - 1)} value={bounded} onChange={e => set({ index: Number(e.target.value), playing: false })} disabled={!play.total}/><span className="min-w-16 text-right text-xs">{play.total ? `${Math.round(100 * bounded / Math.max(1, play.total - 1))}%` : '—'}</span></div>
    <p className="mt-2 text-xs text-slate-500">Keyboard: Space play/pause · ←/→ step · [ / ] change speed · event controls jump to scheduler decisions.</p>
  </div>;
}

function downloadFile(name, data, type) { const url = URL.createObjectURL(new Blob([data], { type })); const anchor = document.createElement('a'); anchor.href = url; anchor.download = name; anchor.click(); URL.revokeObjectURL(url); }

function Timeline({ result, currentTime }) {
  const canvasRef = useRef(null); const baseRef=useRef(null); const timeline = result?.metrics?.timeline || [];
  useEffect(() => {
    if (timeline.length <= 200 || !canvasRef.current) return;
    const base=document.createElement('canvas');base.width=1200;base.height=70;const context=base.getContext('2d'),width=base.width,height=base.height,end=Math.max(1,timeline.at(-1)?.end||1);
    timeline.forEach((segment,index)=>{context.fillStyle=segment.kind==='IDLE'?'#cbd5e1':segment.kind==='SWITCH'?'#fbbf24':`hsl(${(index*61)%360} 65% 42%)`;const x=segment.start/end*width,w=Math.max(1,(segment.end-segment.start)/end*width);context.fillRect(x,0,w,height);});baseRef.current=base;
  }, [timeline]);
  useEffect(()=>{
    if(timeline.length<=200||!canvasRef.current||!baseRef.current)return;const canvas=canvasRef.current,context=canvas.getContext('2d'),width=canvas.width,end=Math.max(1,timeline.at(-1)?.end||1);
    context.clearRect(0,0,canvas.width,canvas.height);context.drawImage(baseRef.current,0,0);context.fillStyle='#0f172a';context.fillRect(Math.min(width-1,currentTime/end*width),0,2,canvas.height);
  },[timeline,currentTime]);
  if (!timeline.length) return <p className="rounded-xl bg-slate-50 p-4 text-sm text-slate-500">Run a workload to create a Gantt chart and event trace.</p>;
  const end = Math.max(1, timeline.at(-1).end);
  return timeline.length > 200 ? <canvas ref={canvasRef} width="1200" height="70" className="w-full rounded border" aria-label="Canvas Gantt chart"/> : <div className="overflow-x-auto rounded-xl border border-slate-200 p-3"><div className="flex min-w-[600px] overflow-hidden rounded-lg">{timeline.map((segment, i) => <div key={`${i}-${segment.start}`} title={`${segment.kind === 'RUN' ? segment.pid : segment.kind}: ${segment.start}–${segment.end}`} className={'min-w-1 border-r border-white px-1 py-2 text-center text-[10px] font-bold text-white ' + (segment.kind === 'IDLE' ? 'bg-slate-400' : segment.kind === 'SWITCH' ? 'bg-amber-500' : 'bg-indigo-700')} style={{ width: `${100 * (segment.end - segment.start) / end}%` }}>{segment.end - segment.start > .5 ? `${segment.kind === 'RUN' ? segment.pid : segment.kind} · ${segment.start}–${segment.end}` : ''}</div>)}</div><div className="relative h-1"><i className="absolute top-0 h-2 w-0.5 bg-rose-600" style={{ left: `${100 * Math.min(currentTime, end) / end}%` }}/></div></div>;
}

function RunViewer({ result, comparison, moduleId }) {
  const play = useSyncExternalStore(subscribePlay, getPlay, getPlay);
  const snapshot = result?.snapshots?.[Math.min(play.index, (result.snapshots?.length || 1) - 1)];
  const time = snapshot?.t ?? play.index;
  let eventLow=0,eventHigh=(result?.events?.length||0)-1,eventIndex=-1;
  while(eventLow<=eventHigh){const mid=(eventLow+eventHigh)>>1;if(result.events[mid].t<=time){eventIndex=mid;eventLow=mid+1;}else eventHigh=mid-1;}
  const currentEvent = eventIndex>=0?result.events[eventIndex]:result?.events?.[0];
  const visibleEvents=snapshot?.processes&&eventIndex>=0?result.events.slice(Math.max(0,eventIndex-99),eventIndex+1):[];
  const metrics = result?.metrics;
  const comparisonTicks = comparison?.metrics?.timeline && metrics?.timeline ? Array.from({length:Math.max(metrics.timeline.at(-1)?.end||0,comparison.metrics.timeline.at(-1)?.end||0)},(_,tick)=>{
    const labelAt=(timeline,time)=>{const item=timeline.find(segment=>segment.start<=time&&time<segment.end);return item?`${item.kind}:${item.pid||''}`:'IDLE:';};
    return {tick,different:labelAt(metrics.timeline,tick)!==labelAt(comparison.metrics.timeline,tick)};
  }) : [];
  const exportJson = () => downloadFile('dmers-os-run.json', JSON.stringify({ seed: result.seed, module: moduleId, context:result.context, events: result.events, snapshots: result.snapshots, metrics: result.metrics, status: result.status }, null, 2), 'application/json');
  const exportCsv = () => { const rows = metrics?.perTask || []; const csv = ['pid,arrival,burst,start,completion,turnaround,waiting,response', ...rows.map(row => [row.pid,row.arrival,row.burst,row.start,row.completion,row.turnaround,row.waiting,row.response].join(','))].join('\n'); downloadFile('dmers-os-metrics.csv', csv, 'text/csv'); };
  const exportPng = () => { const canvas = document.createElement('canvas'); canvas.width = 1200; canvas.height = 160; const context = canvas.getContext('2d'), timeline = metrics?.timeline || [], end = Math.max(1, timeline.at(-1)?.end || 1); context.fillStyle = '#fff'; context.fillRect(0,0,canvas.width,canvas.height); timeline.forEach((item,i) => { context.fillStyle = item.kind === 'IDLE' ? '#94a3b8' : item.kind === 'SWITCH' ? '#f59e0b' : `hsl(${(i*61)%360} 65% 42%)`; const x=item.start/end*canvas.width,w=(item.end-item.start)/end*canvas.width; context.fillRect(x,30,Math.max(w,2),60); context.fillStyle='#fff'; context.font='12px sans-serif'; context.fillText(item.pid || item.kind,x+3,64); }); const link=document.createElement('a'); link.download='dmers-os-gantt.png'; link.href=canvas.toDataURL('image/png'); link.click(); };
  const exportPdf = async () => { const { jsPDF } = await import('jspdf'); const pdf=new jsPDF(); pdf.setFontSize(16); pdf.text('DMERS OS Laboratory Record',14,18); pdf.setFontSize(10); pdf.text(`Module: ${moduleId} · Seed: ${result.seed ?? 'n/a'} · Status: ${result.status ?? 'COMPLETED'}`,14,28); const lines=JSON.stringify(result.metrics || result,null,2).match(/.{1,95}/g)||[]; pdf.text(lines.slice(0,24),14,38); pdf.save('dmers-os-lab-record.pdf'); };
  if (!result) return <div className="rounded-xl border border-dashed border-slate-300 p-8 text-center text-sm text-slate-500">Run the selected teaching model to see its trace, decisions, and measured results.</div>;
  return <div className="space-y-4">
    {result.snapshots && <Playback result={result}/>}
    {metrics?.timeline && <><div className="flex flex-wrap items-center justify-between gap-2"><h3 className="font-bold">CPU timeline · synthetic task ticks</h3><div className="flex flex-wrap gap-2"><button className="secondary" onClick={exportPng}>Export Gantt PNG</button><button className="secondary" onClick={exportCsv}>Metrics CSV</button></div></div><Timeline result={result} currentTime={time}/><div className="grid gap-2 sm:grid-cols-3 xl:grid-cols-6">{[['Avg waiting',metrics.averageWaiting],['Avg turnaround',metrics.averageTurnaround],['Avg response',metrics.averageResponse],['CPU busy',`${(metrics.cpuUtilisation*100).toFixed(1)}%`],['Throughput',metrics.throughput?.toFixed(3)],['Context switches',metrics.contextSwitches]].map(([label,value])=><div key={label} className="rounded-lg bg-indigo-50 p-3 text-xs"><span>{label}</span><b className="mt-1 block text-base">{value ?? '—'}</b></div>)}</div><div className="overflow-x-auto"><table className="w-full text-left text-xs"><thead><tr>{['PID','Arrival','Burst','Priority','First run','Complete','TAT','Waiting','Response','Deadline'].map(label=><th key={label} className="p-2">{label}</th>)}</tr></thead><tbody>{metrics.perTask.map(row=><tr key={row.pid} className="border-t"><td className="p-2 font-bold">{row.pid}</td>{[row.arrival,row.burst,row.priority,row.start ?? 'not run',row.completion ?? 'unfinished',row.turnaround ?? '—',row.waiting,row.response ?? '—',row.deadlineMissed ? 'MISSED' : '—'].map((value,i)=><td className="p-2" key={i}>{value}</td>)}</tr>)}</tbody></table></div><div className="rounded-xl border border-indigo-200 bg-indigo-50 p-3 text-sm"><b>Current decision</b><p className="mt-1">{currentEvent?.reason || 'No event has occurred at this snapshot.'}</p><p className="mt-1 text-xs text-indigo-800">Rule: {metrics.optimalityClaim}</p><p className="mt-1 text-xs">State at t={time}: running <b>{snapshot?.running || 'none'}</b> · ready <b>{snapshot?.ready?.join(', ') || 'empty'}</b></p>{metrics.rateMonotonic && <p className="mt-1">RM utilization {metrics.rateMonotonic.utilization.toFixed(3)} vs sufficient bound {metrics.rateMonotonic.bound.toFixed(3)}. {metrics.rateMonotonic.passesSufficientBound?'Passes this sufficient test.':metrics.missedDeadlines.length?'Above the sufficient bound and this trace misses deadlines.':'Above the sufficient bound, but no deadline miss appeared in this simulated trace; the bound is sufficient, not necessary.'}</p>}</div></>}
    {snapshot?.processes && <div className="overflow-x-auto"><h3 className="font-bold">Process control blocks · virtual clock t={time}</h3><table className="mt-2 w-full text-left text-xs"><thead><tr>{['PID','Parent','Task','State','PC','Priority','Remaining','Resources','CPU ticks','I/O wait','Switches','Cause'].map(label=><th key={label} className="p-2">{label}</th>)}</tr></thead><tbody>{snapshot.processes.slice(0,100).map(process=><tr key={process.pid} className="border-t"><td className="p-2">{process.pid}</td><td className="p-2">{process.parent || '—'}</td><td className="p-2">{process.task}</td><td className="p-2 font-bold">{process.state}</td><td className="p-2">{process.pc}</td><td className="p-2">{process.priority}</td><td className="p-2">{process.remaining}</td><td className="p-2">{process.resourcesHeld.join(', ')||'—'}</td><td className="p-2">{process.accumulatedCpu}</td><td className="p-2">{process.ioWait}</td><td className="p-2">{process.contextSwitches}</td><td className="p-2">{process.cause}</td></tr>)}</tbody></table><h4 className="mt-4 font-bold">Recent transition log · last 100 events</h4><div className="max-h-52 space-y-1 overflow-auto">{visibleEvents.map((event,index)=><p className="rounded bg-slate-50 p-2 text-xs" key={`${event.t}-${index}`}>t={event.t} · {event.detail} — {event.reason}</p>)}</div></div>}
    {comparison && metrics?.perTask && <div className="rounded-xl border border-cyan-200 bg-cyan-50 p-4"><h3 className="font-bold">Synchronized policy comparison</h3><p className="text-xs">Same workload and seed; red ticks mark where process identity or idle/running state differs.</p><div className="mt-2 flex flex-wrap gap-1" aria-label="Per-tick policy difference strip">{comparisonTicks.map(item=><span key={item.tick} title={`t=${item.tick}: ${item.different?'policies diverge':'same state'}`} className={'h-5 w-3 rounded-sm '+(item.different?'bg-rose-500':'bg-emerald-500')+(item.tick===Math.floor(time)?' ring-2 ring-slate-900 ring-offset-1':'')}/>)}</div><p className="text-xs">Diverging ticks: {comparisonTicks.filter(item=>item.different).length}/{comparisonTicks.length} · current virtual time {time}</p><div className="mt-2 grid gap-3 md:grid-cols-2">{[result,comparison].map((run,index)=><article key={index} className="rounded-lg bg-white p-3"><b>{index?'Comparison':'Primary'} · {run.metrics.optimalityClaim}</b><div className="mt-2 flex flex-wrap gap-1">{run.metrics.timeline.map((slot,i)=><span key={i} className="rounded bg-indigo-100 px-2 py-1 text-[10px]">{slot.kind==='RUN'?slot.pid:slot.kind} {slot.start}–{slot.end}</span>)}</div><p className="mt-2 text-xs">Mean waiting {run.metrics.averageWaiting.toFixed(2)} · mean response {run.metrics.averageResponse.toFixed(2)}</p></article>)}</div></div>}
    {!metrics?.timeline && !snapshot?.processes && <div className="rounded-xl bg-slate-50 p-4"><h3 className="font-bold">Measured result</h3><ModuleResult result={result} moduleId={moduleId}/></div>}
    <div className="flex flex-wrap gap-2"><button className="secondary" onClick={exportJson}>Export full run JSON</button><button className="secondary" onClick={exportPdf}>Export one-page lab record PDF</button></div>
  </div>;
}

function ModuleResult({ result, moduleId }) {
  if (moduleId === 'beds') return <BedResult result={result}/>;
  if (moduleId === 'virtual') return <div className="space-y-4"><p className="text-sm">Optimal requires future knowledge and is a benchmark bound, not an online policy. Frames represent staged vehicles; references are zone demand.</p><div className="grid gap-2 md:grid-cols-5">{result.results.map(item=><article key={item.algorithm} className="rounded-lg bg-white p-3"><b>{item.algorithm}</b><p>Faults {item.faults} · hits {item.hits} · hit ratio {(item.hitRatio*100).toFixed(1)}%</p><div className="mt-2 max-h-36 overflow-auto text-[10px]">{item.trace.map(row=><p key={row.referenceIndex}>ref {row.page} → [{row.frames.join(', ')}] {row.hit?'hit':'fault'}</p>)}</div></article>)}</div><h4 className="font-bold">Belady’s anomaly · verified FIFO trace</h4><p>3 frames: {result.belady.threeFrames.faults} faults · 4 frames: {result.belady.fourFrames.faults} faults.</p><div className="flex flex-wrap gap-1">{result.belady.references.map((page,i)=><span key={i} className="rounded bg-indigo-100 px-2 py-1 text-xs">{page}: {result.belady.threeFrames.trace[i].hit?'H':'F'} / {result.belady.fourFrames.trace[i].hit?'H':'F'}</span>)}</div><h4 className="font-bold">Working-set pressure curve</h4><div className="flex h-28 items-end gap-2">{result.thrashing.map(point=><div key={point.frames} className="flex-1 bg-rose-400" title={`${point.frames} frames: ${point.faults} faults`} style={{height:`${Math.max(6,point.faults/Math.max(1,...result.thrashing.map(row=>row.faults))*100)}%`}}><small className="block -mt-5 text-center text-[10px]">{point.faults}</small></div>)}</div></div>;
  if (moduleId === 'disk') return <div className="space-y-4"><div className="grid gap-2 md:grid-cols-3">{result.results.map(item=><article key={item.algorithm} className="rounded-lg bg-white p-3"><b>{item.algorithm}</b><p>Path {item.path.join(' → ')}</p><p>Total movement {item.totalMovement} · mean seek {item.averageSeek.toFixed(2)}</p>{item.starvationRisk&&<small>{item.starvationRisk}</small>}</article>)}</div><h4 className="font-bold">Block allocation layouts</h4><div className="grid gap-2 md:grid-cols-3">{result.files.map(item=><article key={item.scheme} className="rounded-lg bg-white p-3"><b>{item.scheme}</b><p>{item.randomAccessCost}</p><p>{item.fragmentation}</p></article>)}</div></div>;
  if (moduleId === 'memory') return <div className="grid gap-2 md:grid-cols-2"><p>Placement {result.allocation.strategy}: {result.allocation.placements.map(item=>`${item.request}@${item.start} (${item.size})`).join(' · ')}. Largest hole {result.allocation.largestHole}; external fragmentation {(result.allocation.externalFragmentation*100).toFixed(1)}%.</p><p>Compaction merges {result.compaction.before.holeCount} holes into {result.compaction.after.largestHole} free units.</p><p>Paging translation: page {result.paging.page}, offset {result.paging.offset}, frame {result.paging.frame}; physical address {result.paging.physicalAddress} ({result.paging.arithmetic}). Final-page internal fragmentation: {result.fragmentation.internalFragmentation} units.</p><p>Segmentation trap: {result.segmentationTrap.trap}</p><p>TLB effective access time: {result.tlb} time units under configured hit ratio and access timings.</p></div>;
  if (moduleId === 'sync') return <div className="space-y-4"><div className="grid gap-3 md:grid-cols-2"><article className="rounded-lg border border-rose-200 bg-rose-50 p-3"><b>Unsynchronised · expected {result.race.unsynchronized.expected}, actual {result.race.unsynchronized.actual}</b><p className="text-xs">Seed {result.race.seed} · lost update {String(result.race.unsynchronized.lostUpdate)}</p>{result.race.unsynchronized.operations.map((item,index)=><p key={index} className={'mt-1 rounded p-1 font-mono text-xs '+(item.lostUpdateParticipant?'bg-rose-200 font-bold text-rose-950':'bg-white')}>{item.actor} {item.instruction} {item.value}{item.lostUpdateParticipant?' · conflicting read/modify/write':''}</p>)}</article><article className="rounded-lg border border-emerald-200 bg-emerald-50 p-3"><b>Mutex · expected {result.race.mutex.expected}, actual {result.race.mutex.actual}</b><p className="text-xs">Acquisition order replayed from the same seed: {result.race.mutex.acquisitionOrder.join(' → ')}</p>{result.race.mutex.operations.map((item,index)=><p key={index} className="mt-1 rounded bg-white p-1 font-mono text-xs">🔒 {item.actor} {item.instruction} {item.value}</p>)}</article></div><div className="grid gap-2 md:grid-cols-2"><p>Peterson mutual exclusion {String(result.peterson.mutualExclusion)}; progress {String(result.peterson.progress)}; bounded wait {String(result.peterson.boundedWaiting)}. {result.peterson.caveat}</p><p>Semaphore remains non-negative: {String(result.semaphore.invariant)}. Bounded-buffer states: {result.producerConsumer.trace.map(item=>item.state).join(', ')}.</p><p>Readers-writers ({result.readersWriters.policy}): writer blocked through the finite observation window {String(result.readersWriters.writerBlockedThroughHorizon)}. {result.readersWriters.note}</p><p>Dining philosophers: deadlocked {String(result.philosophers.deadlocked)} with {result.philosophers.fix} policy; progress {String(result.philosophers.progress)}. {result.philosophers.note} {result.philosophers.boundedWaitingNote}</p><p>Priority inversion {result.inversion.inheritance?'with':'without'} inheritance: bounded={String(result.inversion.bounded)}. {result.inversion.example}</p></div></div>;
  if (moduleId === 'deadlock') return <div className="grid gap-3 md:grid-cols-2"><div><svg viewBox="0 0 300 180" role="img" aria-label="Wait-for graph"><defs><marker id="wait-arrow" markerWidth="8" markerHeight="8" refX="6" refY="3" orient="auto"><path d="M0,0 L0,6 L7,3 z" fill={result.cycles.length?'#e11d48':'#059669'}/></marker></defs>{result.edges.map(([from,to],index)=>{const points={P0:[60,50],P1:[230,50],P2:[145,145]},a=points[from],b=points[to];return <line key={index} x1={a[0]} y1={a[1]} x2={b[0]} y2={b[1]} stroke={result.cycles.length?'#e11d48':'#059669'} strokeWidth="3" markerEnd="url(#wait-arrow)"/>;})}{[['P0',60,50],['P1',230,50],['P2',145,145]].map(([pid,x,y])=><g key={pid}><circle cx={x} cy={y} r="22" fill="#fff" stroke={result.cycles.length?'#e11d48':'#059669'} strokeWidth="3"/><text x={x} y={y+5} textAnchor="middle" fontSize="13" fontWeight="bold">{pid}</text></g>)}</svg><b>Wait-for graph · {result.cycles.length?'cycle detected':'no cycle'}</b></div><div className="space-y-2 text-sm"><p>Cycle(s): {result.cycles.map(cycle=>cycle.join(' → ')).join(' · ')||'none'}.</p><p>Detection leaves blocked: {result.detection.deadlocked.join(', ')||'none'}. {result.detection.reason||''}</p><p>Coffman conditions: {result.conditions.map(condition=>`${condition.label} ${condition.holds?'holds':'broken'}`).join('; ')}.</p><p>{result.resolvedByPrevention?'The selected scenario breaks a necessary Coffman condition; the cycle is prevented.':`Recovery picks ${result.recovery.victim}; resources after recovery [${result.recovery.resourcesAfter.join(', ')}]. ${result.recovery.costRule}`}</p></div></div>;
  if (moduleId === 'ipc') return <div className="grid gap-2 md:grid-cols-2"><p>Shared memory copies {result.sharedVsMessage.sharedMemory.bytesCopied} bytes and needs synchronization; message passing copies {result.sharedVsMessage.messagePassing.bytesCopied} bytes for this workload.</p><p>Mailbox events: {result.mailbox.events.map(event=>event.type).join(', ')}. Queue after one read: {result.mailbox.queue.join(', ')||'empty'}.</p><p>Pipe consumed: {result.pipe.received.join(', ')}.</p><p>Signal trace: {result.signal.events.map(event=>event.type).join(' → ')}; resumed at PC {result.signal.resumedAt}.</p></div>;
  return <pre className="max-h-96 overflow-auto whitespace-pre-wrap text-xs">{JSON.stringify(result, null, 2)}</pre>;
}

function BankerPanel() {
  const maximum=[[7,5,3],[3,2,2],[9,0,2],[2,2,2],[4,3,3]], initialAllocation=[[0,1,0],[2,0,0],[3,0,2],[2,1,1],[0,0,2]], initialAvailable=[3,3,2];
  const [allocation,setAllocation]=useState(initialAllocation),[available,setAvailable]=useState(initialAvailable),[processIndex,setProcessIndex]=useState(1),[request,setRequest]=useState([1,0,2]),[message,setMessage]=useState('');
  const safe=bankerSafeSequence(available,allocation,maximum);
  const evaluate=()=>{const result=evaluateBankerRequest(available,allocation,maximum,Number(processIndex),request);if(result.granted){setAvailable(result.available);setAllocation(result.allocation);}setMessage(`${result.message}${result.order?` Safe order: ${result.order.join(' → ')}.`:''}`);};
  const correctedCase=()=>{const first=evaluateBankerRequest(initialAvailable,initialAllocation,maximum,1,[1,0,2]);if(!first.granted){setMessage(`Unexpected first request result: ${first.message}`);return;}setAvailable(first.available);setAllocation(first.allocation);const second=evaluateBankerRequest(first.available,first.allocation,maximum,0,[0,2,0]);setMessage(`Correction check: P1 [1,0,2] granted. Then P0 [0,2,0] ${second.granted?'was granted':'was refused'}; the refused request did not mutate the P1-granted state. ${second.message}`);};
  const reset=()=>{setAllocation(initialAllocation.map(row=>[...row]));setAvailable([...initialAvailable]);setMessage('Reset to the textbook state.');};
  return <section className="mt-4 rounded-2xl border border-violet-200 bg-violet-50 p-4"><div className="flex flex-wrap justify-between gap-2"><div><h3 className="font-bold text-violet-950">Banker’s algorithm · avoidance</h3><p className="text-xs text-violet-800">Need = Max − Allocation. A denied tentative request never changes the committed state.</p></div><button className="secondary" onClick={correctedCase}>Run corrected textbook request case</button></div><p className="mt-2 text-sm">Available [{available.join(', ')}] · state <b>{safe.safe?'SAFE':'UNSAFE'}</b> · sequence {safe.safe?safe.order.join(' → '):'none'}</p><div className="mt-2 overflow-x-auto"><table className="w-full text-left text-xs"><thead><tr>{['Process','Allocation','Max','Need'].map(item=><th className="p-2" key={item}>{item}</th>)}</tr></thead><tbody>{allocation.map((row,index)=><tr className="border-t border-violet-200" key={index}><td className="p-2">P{index}</td><td className="p-2">{row.join(', ')}</td><td className="p-2">{maximum[index].join(', ')}</td><td className="p-2">{safe.need[index].join(', ')}</td></tr>)}</tbody></table></div><div className="mt-3 flex flex-wrap items-end gap-2"><label>Requesting process<select value={processIndex} onChange={e=>setProcessIndex(Number(e.target.value))}>{allocation.map((_,index)=><option value={index} key={index}>P{index}</option>)}</select></label>{['A','B','C'].map((resource,index)=><label key={resource}>Request {resource}<input type="number" min="0" value={request[index]} onChange={e=>setRequest(items=>items.map((value,i)=>i===index?Number(e.target.value):value))}/></label>)}<button className="primary" onClick={evaluate}>Evaluate request</button><button className="secondary" onClick={reset}>Reset</button></div><details className="mt-3 rounded-lg bg-white p-3 text-xs"><summary>Show Work vector trace</summary>{safe.workTrace.map((item,index)=><p key={index}>{index?`${item.process} finishes; `:'Initial Work: '}Work = [{item.work.join(', ')}]</p>)}</details>{message&&<p role="status" className="mt-3 rounded-lg bg-white p-3 text-sm">{message}</p>}</section>;
}

export default function OSLaboratory() {
  const [moduleId, setModuleId] = useState('cpu');
  const [algorithm, setAlgorithm] = useState('FCFS');
  const [comparisonAlgorithm, setComparisonAlgorithm] = useState('SRTF');
  const [quantum, setQuantum] = useState(2), [contextSwitchCost, setContextSwitchCost] = useState(0), [agingInterval, setAgingInterval] = useState(3);
  const [seed, setSeed] = useState('2026');
  const [workload, setWorkload] = useState([{ pid:'P1',name:'SOS intake',arrival:0,burst:5,priority:2,deadline:8,period:6 },{ pid:'P2',name:'Incident verification',arrival:1,burst:3,priority:3,deadline:10,period:8 },{ pid:'P3',name:'Hospital notification',arrival:2,burst:4,priority:1,deadline:12,period:10 }]);
  const [result, setResult] = useState(null), [comparison, setComparison] = useState(null), [busy, setBusy] = useState(false), [notice, setNotice] = useState('Choose a concept, edit the workload, then run a repeatable simulation.');
  const [conceptOpen, setConceptOpen] = useState(false), [challenge, setChallenge] = useState(null), [challengeChoice, setChallengeChoice] = useState('');
  const [labInputs, setLabInputs] = useState({ references:'1,2,3,4,1,2,5,1,2,3,4,5',frames:3,maxFrames:8,requests:'98,183,37,122,14,124,65,67',head:53,direction:'right',capacity:2,readerPolicy:'reader-preference',philosopherFix:'none',inheritance:false,allocation:'BEST_FIT',address:14,ambulances:10,dispatchers:2,count:4,bytes:64,...BED_DEFAULTS });
  const [conditions, setConditions] = useState({ mutualExclusion:true,holdAndWait:true,noPreemption:true,circularWait:true });
  const selectedConcept = concepts[moduleId];
  useEffect(() => { setResult(null); setComparison(null); setNotice('Edit inputs and run this teaching model.'); setChallenge(null); }, [moduleId]);
  const setField = (index, key, value) => setWorkload(items => items.map((item, i) => i === index ? { ...item, [key]: value } : item));
  const addTask = () => setWorkload(items => items.length>=100?items:[...items, { pid:`P${items.length+1}`,name:'New response task',arrival:0,burst:2,priority:5,deadline:12,period:10 }]);
  const forkFirst = () => { const parent=workload[0]; if(!parent)return; const children=forkIncident({pid:parent.pid,priority:Number(parent.priority)}).map(child=>({pid:child.pid,parent:child.parent,name:child.task,arrival:Number(parent.arrival),burst:3,bursts:child.bursts,priority:child.priority,deadline:Number(parent.deadline),period:Number(parent.period)})); setWorkload(items=>items.length+children.length<=100?[...items,...children]:items); };
  const randomize = () => { const random=mulberry32(Number(seed)||1); setWorkload(Array.from({length:4},(_,i)=>({pid:`P${i+1}`,name:['SOS intake','Route assessment','Hospital call','Supply request'][i],arrival:Math.floor(random()*5),burst:1+Math.floor(random()*7),priority:1+Math.floor(random()*8),deadline:7+Math.floor(random()*18),period:5+Math.floor(random()*16)}))); setNotice(`Generated a reproducible workload from seed ${seed}.`); };
  const presets = {
    textbook:[{pid:'P1',name:'Dispatch log',arrival:0,burst:6,priority:2,deadline:20,period:20},{pid:'P2',name:'Incident verification',arrival:0,burst:2,priority:1,deadline:12,period:12},{pid:'P3',name:'Hospital notification',arrival:0,burst:4,priority:3,deadline:18,period:18}],
    convoy:[{pid:'P1',name:'Long convoy task',arrival:0,burst:12,priority:4,deadline:30,period:30},{pid:'P2',name:'Short SOS intake',arrival:1,burst:1,priority:1,deadline:6,period:6},{pid:'P3',name:'Short hospital call',arrival:2,burst:2,priority:2,deadline:8,period:8}],
    starvation:[{pid:'P1',name:'Continuous critical queue',arrival:0,burst:8,priority:1,deadline:12,period:12},{pid:'P2',name:'Low-priority inspection',arrival:0,burst:3,priority:8,deadline:18,period:18},{pid:'P3',name:'New urgent event',arrival:2,burst:4,priority:1,deadline:10,period:10}],
    belady:[{pid:'P1',name:'Depot reference stream',arrival:0,burst:12,priority:3,deadline:20,period:20}],
    priority:[{pid:'P1',name:'Low priority board update',arrival:0,burst:5,priority:8,deadline:18,period:18},{pid:'P2',name:'High priority emergency',arrival:2,burst:1,priority:1,deadline:5,period:5},{pid:'P3',name:'Medium priority sync',arrival:1,burst:3,priority:4,deadline:10,period:10}],
    deadlock:[{pid:'P0',name:'Hold radio A; request B',arrival:0,burst:2,priority:2,deadline:10,period:10},{pid:'P1',name:'Hold radio B; request A',arrival:0,burst:2,priority:4,deadline:10,period:10}],
  };
  const loadPreset = name => { if(name==='belady'){setModuleId('virtual');setLabInputs(value=>({...value,references:'1,2,3,4,1,2,5,1,2,3,4,5'}));} else {setWorkload(presets[name]);setModuleId(name==='deadlock'?'deadlock':'cpu');} setNotice(`Loaded ${name} teaching workload.`); };
  const run = async () => {
    setBusy(true); setNotice('Worker is computing the complete deterministic trace…'); setResult(null); setComparison(null); setChallenge(null);
    try {
      let output, comparisonOutput = null;
      if(moduleId==='cpu') {
        const base={workload,seed:Number(seed)||1,maxSteps:10000};
      const params={algorithm,quantum:Number(quantum),contextSwitchCost:Number(contextSwitchCost),agingInterval:Number(agingInterval)};
        [output,comparisonOutput]=await Promise.all([runInWorker({model:'cpu',...base,params}),comparisonAlgorithm?runInWorker({model:'cpu',...base,params:{...params,algorithm:comparisonAlgorithm}}):Promise.resolve(null)]);
      } else if(moduleId==='process') output=await runInWorker({model:'process',workload:workload.map(task=>({...task,bursts:task.bursts||[Number(task.burst),2]})),seed:Number(seed)||1,maxSteps:1000});
      else output=await runInWorker({model:'lab',kind:moduleId,inputs:{...labInputs,conditions,seed:Number(seed)||1}});
      const context={module:moduleId,seed:Number(seed)||1,workload:['cpu','process'].includes(moduleId)?workload:undefined,algorithm,comparisonAlgorithm,quantum:Number(quantum),contextSwitchCost:Number(contextSwitchCost),agingInterval:Number(agingInterval),inputs:!['cpu','process'].includes(moduleId)?{...labInputs,conditions}:undefined};
      setResult({...output,seed:Number(seed)||1,context}); setComparison(comparisonOutput); setNotice(output.status ? `Complete trace ready · ${output.status} · seed ${output.seed}. Playback scrubs cached snapshots; it will not recalculate.` : 'Worker completed this deterministic model.');
      if(moduleId==='cpu'&&output.metrics?.timeline?.length) setChallenge({answer:output.metrics.timeline.find(item=>item.kind==='RUN')?.pid,points:0});
    } catch(error) { setNotice(`Simulation failed: ${error.message}`); }
    finally { setBusy(false); }
  };
  const answerChallenge = () => { if(!challenge) return; const correct=challengeChoice===challenge.answer; setChallenge(value=>({...value,done:true,correct,points:value.points+(correct?1:0)})); };
  const algorithms = ['FCFS','SJF','SRTF','PRIORITY','PRIORITY_PREEMPTIVE','PRIORITY_AGING','RR','MLFQ','EDF','RM'];
  return <section className="mx-auto mt-4 max-w-[1500px] space-y-4">
    <header className="overflow-hidden rounded-2xl bg-gradient-to-r from-indigo-950 via-slate-900 to-cyan-950 p-6 text-white shadow-lg"><span className="text-xs font-bold tracking-[.2em] text-cyan-300">BCSE303L + BCSE303P · OPERATING SYSTEMS</span><h2 className="mt-2 text-2xl font-black sm:text-3xl">DMERS OS Laboratory</h2><p className="mt-2 max-w-4xl text-sm text-slate-200">Step through the systems behind response coordination. Every run uses synthetic training inputs; it does not touch incident dispatch, real teams, or the host operating system.</p><p className="mt-3 inline-flex rounded-full border border-amber-400/60 bg-amber-300/10 px-3 py-1 text-xs font-semibold text-amber-100">TRAINING PROTOTYPE · computed operational figures require human verification</p></header>
    <div className="grid gap-4 xl:grid-cols-[220px_minmax(0,1fr)]"><nav className="flex gap-2 overflow-x-auto xl:flex-col xl:overflow-visible" aria-label="Operating systems concepts">{modules.map(([id,title,subtitle])=><button key={id} onClick={()=>setModuleId(id)} className={'min-w-40 rounded-xl border p-3 text-left transition xl:min-w-0 '+(moduleId===id?'border-indigo-700 bg-indigo-950 text-white shadow':'border-slate-200 bg-white hover:border-indigo-300')}><b className="block">{title}</b><small className={'mt-1 block text-xs '+(moduleId===id?'text-indigo-100':'text-slate-500')}>{subtitle}</small></button>)}</nav>
      <div className="min-w-0 space-y-4">
        <section className="rounded-2xl border border-slate-200 bg-white p-4 shadow-sm dark:border-slate-700 dark:bg-slate-900"><div className="flex flex-wrap items-start justify-between gap-3"><div><h3 className="text-xl font-extrabold">{modules.find(item=>item[0]===moduleId)?.[1]}</h3><p className="mt-1 text-sm text-slate-500">{modules.find(item=>item[0]===moduleId)?.[2]}</p></div><button className="secondary" onClick={()=>setConceptOpen(value=>!value)}>{conceptOpen?'Hide':'Open'} concept card</button></div>
        {conceptOpen&&<article className="mt-4 grid gap-4 rounded-xl bg-slate-50 p-4 md:grid-cols-2"><div><b>Definition</b><p className="text-sm">{selectedConcept.definition}</p><b className="mt-3 block">Formula</b><p className="text-sm">{selectedConcept.formulas}</p><b className="mt-3 block">Guarantee and conditions</b><p className="text-sm">{selectedConcept.guarantee}</p></div><div><b>Common misconceptions</b><ul className="list-disc pl-5 text-sm">{selectedConcept.myths.map(item=><li key={item}>{item}</li>)}</ul><b className="mt-3 block">Viva questions</b><details className="mt-1 rounded border bg-white p-2 text-sm"><summary>Show questions and answers</summary>{selectedConcept.viva.map(([q,a])=><p className="mt-2" key={q}><b>{q}</b><br/>{a}</p>)}</details></div></article>}
        </section>

        {['cpu','process'].includes(moduleId)&&<section className="rounded-2xl border border-slate-200 bg-white p-4 shadow-sm"><div className="flex flex-wrap items-end justify-between gap-3"><div><h3 className="font-bold">Workload editor</h3><p className="text-xs text-slate-500">Processes model incidents; burst is estimated CPU service ticks; deadlines model synthetic response windows; priorities use lower number = higher priority.</p></div><div className="flex flex-wrap gap-2"><label>Seed<input className="w-28" type="number" value={seed} onChange={e=>setSeed(e.target.value)}/></label><button className="secondary" onClick={randomize}>Randomize from seed</button><button className="secondary" onClick={addTask}>Add process</button>{moduleId==='process'&&<button className="secondary" onClick={forkFirst}>Fork triage / transport / supply</button>}</div></div>
          <div className="mt-3 flex flex-wrap gap-2"><span className="text-xs font-bold">Presets:</span>{['textbook','convoy','starvation','belady','priority','deadlock'].map(name=><button key={name} className="rounded-full bg-slate-100 px-3 py-1 text-xs hover:bg-indigo-100" onClick={()=>loadPreset(name)}>{name}</button>)}</div>
          {moduleId==='cpu'&&<div className="mt-4 grid gap-3 md:grid-cols-4"><label>Algorithm<select value={algorithm} onChange={e=>setAlgorithm(e.target.value)}>{algorithms.map(value=><option key={value} value={value}>{value.replaceAll('_',' ')}</option>)}</select></label><label>Compare with<select value={comparisonAlgorithm} onChange={e=>setComparisonAlgorithm(e.target.value)}><option value="">No comparison</option>{algorithms.filter(value=>value!==algorithm).map(value=><option key={value}>{value}</option>)}</select></label><label>RR quantum<input type="number" min="1" value={quantum} onChange={e=>setQuantum(e.target.value)}/></label><label>Context-switch cost<input type="number" min="0" value={contextSwitchCost} onChange={e=>setContextSwitchCost(e.target.value)}/></label><label>Aging interval<input type="number" min="1" value={agingInterval} onChange={e=>setAgingInterval(e.target.value)}/></label></div>}
          <div className="mt-4 overflow-x-auto"><table className="w-full min-w-[760px] text-left text-xs"><thead><tr>{['PID','Task','Arrival','Burst','Priority','Deadline','Period','Order',''].map(label=><th key={label} className="p-2">{label}</th>)}</tr></thead><tbody>{workload.map((task,index)=><tr className="border-t" key={task.pid}><td className="p-1"><input aria-label={`${task.pid} process id`} value={task.pid} onChange={e=>setField(index,'pid',e.target.value)}/></td><td className="p-1"><input aria-label={`${task.pid} task name`} value={task.name} onChange={e=>setField(index,'name',e.target.value)}/></td>{['arrival','burst','priority','deadline','period'].map(key=><td className="p-1" key={key}><input aria-label={`${task.pid} ${key}`} type="number" min={key==='priority'?0:1} value={task[key]} onChange={e=>setField(index,key,Number(e.target.value))}/></td>)}<td className="p-1"><button className="secondary px-2 py-1" disabled={index===0} onClick={()=>setWorkload(items=>{const copy=[...items];[copy[index-1],copy[index]]=[copy[index],copy[index-1]];return copy})}>↑</button> <button className="secondary px-2 py-1" disabled={index===workload.length-1} onClick={()=>setWorkload(items=>{const copy=[...items];[copy[index+1],copy[index]]=[copy[index],copy[index+1]];return copy})}>↓</button></td><td className="p-1"><button className="text-rose-700" onClick={()=>setWorkload(items=>items.filter((_,i)=>i!==index))} aria-label={`Delete ${task.pid}`}>Delete</button></td></tr>)}</tbody></table></div>
          <div className="mt-4 flex flex-wrap items-center gap-3"><button className="primary" disabled={busy||!workload.length} onClick={run}>{busy?'Computing in worker…':moduleId==='process'?'Run process lifecycle':'Run / compare scheduling policies'}</button><span role="status" className="text-sm text-cyan-800">{notice}</span></div>
        </section>}
        {!['cpu','process'].includes(moduleId)&&<section className="rounded-2xl border border-slate-200 bg-white p-4 shadow-sm"><h3 className="font-bold">Scenario controls</h3><p className="text-xs text-slate-500">Synthetic scenario only. Results are computed in a Web Worker; confirm conventions in the concept card.</p><div className="mt-3 grid gap-3 sm:grid-cols-2 lg:grid-cols-4">{moduleId==='virtual'&&<><label>Reference string<input value={labInputs.references} onChange={e=>setLabInputs(value=>({...value,references:e.target.value}))}/></label><label>Frames<input type="number" min="1" value={labInputs.frames} onChange={e=>setLabInputs(value=>({...value,frames:Number(e.target.value)}))}/></label><label>Max frames on curve<input type="number" min="1" value={labInputs.maxFrames} onChange={e=>setLabInputs(value=>({...value,maxFrames:Number(e.target.value)}))}/></label></>}{moduleId==='disk'&&<><label>Disk head<input type="number" min="0" max="199" value={labInputs.head} onChange={e=>setLabInputs(value=>({...value,head:Number(e.target.value)}))}/></label><label>Requests<input value={labInputs.requests} onChange={e=>setLabInputs(value=>({...value,requests:e.target.value}))}/></label><label>Direction<select value={labInputs.direction} onChange={e=>setLabInputs(value=>({...value,direction:e.target.value}))}><option>right</option><option>left</option></select></label></>}{moduleId==='sync'&&<><label>Ambulances<input type="number" value={labInputs.ambulances} onChange={e=>setLabInputs(value=>({...value,ambulances:Number(e.target.value)}))}/></label><label>Dispatchers<input type="number" value={labInputs.dispatchers} onChange={e=>setLabInputs(value=>({...value,dispatchers:Number(e.target.value)}))}/></label><label>Reader policy<select value={labInputs.readerPolicy} onChange={e=>setLabInputs(value=>({...value,readerPolicy:e.target.value}))}><option value="reader-preference">Reader preference</option><option value="fair">Fair variant</option></select></label><label>Philosopher fix<select value={labInputs.philosopherFix} onChange={e=>setLabInputs(value=>({...value,philosopherFix:e.target.value}))}>{['none','asymmetric','waiter','tryLock'].map(item=><option key={item}>{item}</option>)}</select></label><label className="flex-row items-center gap-2"><input type="checkbox" checked={labInputs.inheritance} onChange={e=>setLabInputs(value=>({...value,inheritance:e.target.checked}))}/>Enable priority inheritance</label></>}{moduleId==='memory'&&<><label>Placement policy<select value={labInputs.allocation} onChange={e=>setLabInputs(value=>({...value,allocation:e.target.value}))}>{['FIRST_FIT','BEST_FIT','WORST_FIT'].map(item=><option key={item}>{item}</option>)}</select></label><label>Logical address<input type="number" value={labInputs.address} onChange={e=>setLabInputs(value=>({...value,address:Number(e.target.value)}))}/></label></>}{moduleId==='ipc'&&<><label>Mailbox capacity<input type="number" min="1" value={labInputs.capacity} onChange={e=>setLabInputs(value=>({...value,capacity:Number(e.target.value)}))}/></label><label>Messages compared<input type="number" min="1" value={labInputs.count} onChange={e=>setLabInputs(value=>({...value,count:Number(e.target.value)}))}/></label><label>Payload bytes<input type="number" min="0" value={labInputs.bytes} onChange={e=>setLabInputs(value=>({...value,bytes:Number(e.target.value)}))}/></label></>}{moduleId==='beds'&&<BedControls inputs={labInputs} setInputs={setLabInputs}/>}{moduleId==='deadlock'&&<div className="grid gap-2 rounded bg-amber-50 p-3 text-sm text-amber-950 sm:col-span-2"><b>Toggle each Coffman condition to demonstrate deadlock prevention:</b>{[['mutualExclusion','Mutual exclusion'],['holdAndWait','Hold and wait'],['noPreemption','No preemption'],['circularWait','Circular wait']].map(([id,label])=><label className="flex-row items-center gap-2" key={id}><input type="checkbox" checked={conditions[id]} onChange={e=>setConditions(value=>({...value,[id]:e.target.checked}))}/>{label} holds</label>)}</div>}</div><button className="primary mt-4" disabled={busy} onClick={run}>{busy?'Computing in worker…':`Run ${modules.find(item=>item[0]===moduleId)?.[1]} demonstration`}</button><span role="status" className="ml-3 text-sm text-cyan-800">{notice}</span></section>}

        {moduleId==='cpu'&&result?.metrics?.timeline&&challenge&&!challenge.done&&<section className="rounded-xl border border-amber-300 bg-amber-50 p-4"><b>Optional challenge · decision point t=0</b><p className="text-sm">Which process does {algorithm} dispatch first in this workload?</p><div className="mt-2 flex flex-wrap gap-2">{workload.map(task=><button key={task.pid} className="secondary" onClick={()=>setChallengeChoice(task.pid)} aria-pressed={challengeChoice===task.pid}>{task.pid} · {task.name}</button>)}<button className="primary" disabled={!challengeChoice} onClick={answerChallenge}>Check answer</button></div></section>}
        {moduleId==='cpu'&&challenge?.done&&<p className="rounded-lg bg-emerald-50 p-3 text-sm">{challenge.correct?'Correct.':'Not quite.'} Expected {challenge.answer}; score {challenge.points}.</p>}
        {moduleId==='deadlock'&&<BankerPanel/>}
        <section className="rounded-2xl border border-slate-200 bg-white p-4 shadow-sm"><RunViewer result={result} comparison={comparison} moduleId={moduleId}/></section>
      </div>
    </div>
  </section>;
}
